-- Postflight: every counter below must be zero.
SELECT CONCAT('race_restricted_bindings=', COUNT(*)) FROM `solitary_bot_gear_template_item` b JOIN `item_template` i ON i.`entry` = b.`item_entry` WHERE i.`AllowableRace` <> -1 AND (i.`AllowableRace` & 1791) <> 1791;
SELECT CONCAT('faction_restricted_bindings=', COUNT(*)) FROM `solitary_bot_gear_template_item` b JOIN `item_template` i ON i.`entry` = b.`item_entry` WHERE (i.`FlagsExtra` & 3) <> 0;
SELECT CONCAT('non_deterministic_bindings=', COUNT(*)) FROM `solitary_bot_gear_template_item` b JOIN `item_template` i ON i.`entry` = b.`item_entry` WHERE i.`duration` <> 0 OR i.`bonding` = 4 OR i.`requiredspell` <> 0 OR i.`HolidayId` <> 0 OR i.`RequiredLevel` > 80 OR i.`ScalingStatDistribution` <> 0;
SELECT CONCAT('limit_category_conflicts=', COUNT(*)) FROM (SELECT b.`template_id`, i.`ItemLimitCategory` FROM `solitary_bot_gear_template_item` b JOIN `item_template` i ON i.`entry` = b.`item_entry` WHERE i.`ItemLimitCategory` <> 0 GROUP BY b.`template_id`, i.`ItemLimitCategory` HAVING COUNT(*) > IF(i.`ItemLimitCategory` = 2, 3, 1)) conflicts;
SELECT CONCAT('heavy_armor_bindings=', COUNT(*)) FROM `solitary_bot_gear_template` t JOIN `solitary_bot_gear_template_item` b ON b.`template_id` = t.`template_id` JOIN `item_template` i ON i.`entry` = b.`item_entry` WHERE i.`class` = 4 AND i.`subclass` IN (1,2,3,4) AND i.`subclass` > CASE WHEN t.`class_id` IN (1,2,6) THEN 4 WHEN t.`class_id` IN (3,7) THEN 3 WHEN t.`class_id` IN (4,11) THEN 2 ELSE 1 END;
SELECT CONCAT('catalogue_shape=', COUNT(*), '/', (SELECT COUNT(*) FROM `solitary_bot_gear_template_item`), '/v', MIN(`template_version`), '-', MAX(`template_version`)) FROM `solitary_bot_gear_template`;

